const signals = $input.first().json;
const regions = ['asia', 'europe', 'americas'];
const heatmap = {};
regions.forEach(r => { heatmap[r] = Math.random(); });
const avgRisk = Object.values(heatmap).reduce((a, b) => a + b, 0) / regions.length;
const affected = ['Supplier_A', 'Supplier_C'].filter(() => Math.random() > 0.5);
const actions = avgRisk > 0.7 ? [{type: 'DIVERSIFY', priority: 'HIGH'}, {type: 'STOCKPILE', priority: 'MEDIUM'}] : [{type: 'MONITOR', priority: 'LOW'}];
return [{json: {risk_heatmap: heatmap, disruption_probability: avgRisk, affected_suppliers: affected, recommended_actions: actions, timestamp: new Date().toISOString()}}];
